window.shmot_elements={lib:{},assets:[],shapes:{},setup:function(h){
const n=h.MovieClip,e=h.Container,a=h.Sprite,z=h.Text,A=h.Graphics;

// ── Вкладка категории ─────────────────────────────────────────────
shmot_elements.lib.Cat_tab=class extends e{
  constructor(label,w){
    super();this._w=w;
    this.bg=new A();this._draw(false);
    const t=new z(label,{fontFamily:'Southbank LT',fontSize:11,fontWeight:'bold',fill:'#a0b878',align:'center',wordWrap:true,wordWrapWidth:w-6});
    t.anchor.set(0.5,0.5);t.x=w/2;t.y=19;this[t.name='label_txt']=t;
    this.addChild(this.bg,t);this.interactive=true;this.buttonMode=true;
    this.on('mouseover',()=>{if(!this._active)this._draw('hover');});
    this.on('mouseout',()=>{if(!this._active)this._draw(false);});
  }
  _draw(s){
    this.bg.clear();
    if(s==='active'){this.bg.beginFill(0x152808,1);this.bg.lineStyle(1,0x4a8028);}
    else if(s==='hover'){this.bg.beginFill(0x0c1806,1);this.bg.lineStyle(1,0x284818,0.7);}
    else{this.bg.beginFill(0x070d05,0.9);this.bg.lineStyle(1,0x162408,0.6);}
    this.bg.drawRoundedRect(0,0,this._w,36,4);this.bg.endFill();
  }
  setActive(v){this._active=v;this._draw(v?'active':false);}
};

// ── Слот экипированного предмета (в манекене) ─────────────────────
shmot_elements.lib.Equip_slot=class extends e{
  constructor(slotName){
    super();
    const bg=new A();bg.beginFill(0x0a1408,0.85);bg.lineStyle(1,0x1e3810,0.7);bg.drawRoundedRect(0,0,310,52,4);bg.endFill();
    const lbl=new z(slotName,{fontFamily:'Southbank LT',fontSize:10,fill:'#4a6a3a',letterSpacing:1});lbl.x=8;lbl.y=6;
    const it=new z('Пусто',{fontFamily:'Southbank LT',fontSize:13,fontWeight:'bold',fill:'#2a4a2a'});it.x=8;it.y=24;
    this[it.name='item_txt']=it;
    const bn=new z('',{fontFamily:'Southbank LT',fontSize:11,fill:'#8aa870'});bn.x=8;bn.y=38;
    this[bn.name='bonus_txt']=bn;
    this.addChild(bg,lbl,it,bn);
  }
};

// ── Карточка предмета ─────────────────────────────────────────────
shmot_elements.lib.Shmot_item=class extends e{
  constructor(){
    super();
    this.bg_mc=new A();this._drawBg(false,false);this.addChild(this.bg_mc);
    // Иконка
    const ib=new A();ib.beginFill(0x0c1a08,1);ib.lineStyle(1,0x244020);ib.drawRoundedRect(6,6,54,54,4);ib.endFill();
    const it=new z('',{fontFamily:'Arial',fontSize:26,align:'center'});it.anchor.set(0.5,0.5);it.x=33;it.y=33;
    this[it.name='icon_txt']=it;this.addChild(ib,it);
    // Бейдж «надет»
    const ob=new A();ob.beginFill(0x204808,1);ob.lineStyle(1,0x508020);ob.drawRoundedRect(0,0,56,18,3);ob.endFill();
    const ot=new z('НАДЕТ',{fontFamily:'Southbank LT',fontSize:8,fontWeight:'bold',fill:'#80d020',align:'center'});ot.anchor.set(0.5,0.5);ot.x=28;ot.y=9;
    const ow=new e();ow.addChild(ob,ot);ow.x=4;ow.y=48;ow.visible=false;
    this[ow.name='badge_on']=ow;this.addChild(ow);
    // Название
    const nt=new z('',{fontFamily:'Southbank LT',fontSize:12,fontWeight:'bold',fill:'#c8d060',wordWrap:true,wordWrapWidth:178});nt.x=68;nt.y=6;
    this[nt.name='name_txt']=nt;
    // Бонус
    const bt=new z('',{fontFamily:'Arial',fontSize:11,fill:'#7aa050',wordWrap:true,wordWrapWidth:178});bt.x=68;bt.y=26;
    this[bt.name='bonus_txt']=bt;
    // Цена
    const pt=new z('',{fontFamily:'Southbank LT',fontSize:11,fill:'#c8a030'});pt.x=68;pt.y=48;
    this[pt.name='price_txt']=pt;
    // Кнопка
    const bbg=new A();bbg.beginFill(0x152808,1);bbg.lineStyle(1,0x3a6818);bbg.drawRoundedRect(0,0,76,24,3);bbg.endFill();
    const bt2=new z('НАДЕТЬ',{fontFamily:'Southbank LT',fontSize:10,fontWeight:'bold',fill:'#90d030',align:'center'});bt2.anchor.set(0.5,0.5);bt2.x=38;bt2.y=12;
    const bb=new e();bb.addChild(bbg,bt2);bb.x=176;bb.y=40;
    bb.interactive=true;bb.buttonMode=true;
    bb.on('mouseover',()=>bbg.tint=0xcceeaa);bb.on('mouseout',()=>bbg.tint=0xffffff);
    this[bb.name='butt_wear']=bb;this[bt2.name='wear_txt']=bt2;
    this.addChild(nt,bt,pt,ow,bb);
  }
  _drawBg(on,locked){
    this.bg_mc.clear();
    if(on){this.bg_mc.beginFill(0x0e2408,0.95);this.bg_mc.lineStyle(2,0x3a7018,0.9);}
    else if(locked){this.bg_mc.beginFill(0x070b05,0.7);this.bg_mc.lineStyle(1,0x111c08,0.5);}
    else{this.bg_mc.beginFill(0x090f06,0.9);this.bg_mc.lineStyle(1,0x1a3010,0.7);}
    this.bg_mc.drawRoundedRect(0,0,258,68,5);this.bg_mc.endFill();
  }
  setState(on,locked){
    this._drawBg(on,locked);this.badge_on.visible=on;
    this.alpha=locked?0.5:1;
    this.wear_txt.text=locked?'КУПИТЬ':on?'СНЯТЬ':'НАДЕТЬ';
    const c=locked?0x3a2a00:on?0x3a7018:0x152808;
    // цвет кнопки меняем через tint bg_mc.children[0]? Нет, проще через буфер
  }
};

// ── Главное окно Шмоток ────────────────────────────────────────────
shmot_elements.lib.Shmot_win=class extends e{
  constructor(){
    super();
    const wb=new A();wb.beginFill(0x050c03,0.97);wb.lineStyle(2,0x285018,0.9);wb.drawRoundedRect(0,0,1200,524,6);wb.endFill();
    this.addChild(wb);
    const hb=new A();hb.beginFill(0x081802,1);hb.drawRect(2,2,1196,42);hb.endFill();
    const hl=new A();hl.lineStyle(1,0x285018,0.5);hl.moveTo(2,45);hl.lineTo(1198,45);
    this.addChild(hb,hl);
    const ttl=new z('ШМОТКИ',{fontFamily:'Southbank LT',fontSize:18,fontWeight:'bold',fill:'#b8d840',letterSpacing:5,dropShadow:true,dropShadowDistance:2,dropShadowColor:'#000'});
    ttl.x=20;ttl.y=12;this.addChild(ttl);
    const cbg=new A();cbg.beginFill(0x3a1010,1);cbg.lineStyle(1,0x882222);cbg.drawRoundedRect(0,0,30,30,4);cbg.endFill();
    const ctx=new z('×',{fontFamily:'Arial',fontSize:22,fill:'#cc4444'});ctx.anchor.set(0.5,0.5);ctx.x=15;ctx.y=15;
    const cl=new e();cl.addChild(cbg,ctx);cl.x=1162;cl.y=7;
    cl.interactive=true;cl.buttonMode=true;cl.on('mouseover',()=>cbg.tint=0xddaaaa);cl.on('mouseout',()=>cbg.tint=0xffffff);
    this[cl.name='butt_close']=cl;this.addChild(cl);

    // Разделитель манекен | сетка
    const div=new A();div.lineStyle(1,0x1e3810,0.5);div.moveTo(328,48);div.lineTo(328,520);this.addChild(div);

    // ── Манекен (левая панель 320px) ──────────────────────────────
    const man=new e();man.x=8;man.y=50;
    // Силуэт тела
    const body=new A();
    body.beginFill(0x0c1a08,1);body.lineStyle(1,0x224018,0.6);
    body.drawRoundedRect(55,0,100,30,15); // голова
    body.drawRoundedRect(30,32,150,100,8); // торс
    body.drawRect(30,134,60,120);          // левая нога
    body.drawRect(120,134,60,120);         // правая нога
    body.drawRect(0,32,28,90);             // левая рука
    body.drawRect(182,32,28,90);           // правая рука
    body.endFill();
    // Подпись
    const mlbl=new z('ПЕРСОНАЖ',{fontFamily:'Southbank LT',fontSize:10,fill:'#3a5028',letterSpacing:3,align:'center'});mlbl.anchor.set(0.5);mlbl.x=105;mlbl.y=265;
    man.addChild(body,mlbl);
    // Слоты экипировки
    const slot_names=['👒 Голова','🧥 Тело','👖 Штаны','👟 Обувь','💍 Аксессуар','🖊 Татуировка'];
    const slots=new e();slots.x=0;slots.y=280;
    for(let i=0;i<6;i++){
      const sl=new shmot_elements.lib.Equip_slot(slot_names[i]);sl.y=i*58;
      slots['slot_'+i]=sl;slots.addChild(sl);
    }
    this[slots.name='equip_slots']=slots;man.addChild(slots);
    this[man.name='mannequin']=man;this.addChild(man);

    // ── Правая панель: вкладки + сетка ────────────────────────────
    const cat_names=['Голова','Тело','Штаны','Обувь','Аксессуар','Татуировки'];
    const tw=141,tg=3;
    const tabs=new e();tabs.x=336;tabs.y=50;
    for(let i=0;i<6;i++){const tb=new shmot_elements.lib.Cat_tab(cat_names[i],tw);tb.x=i*(tw+tg);tabs['tab_'+i]=tb;tabs.addChild(tb);}
    this[tabs.name='cat_tabs']=tabs;this.addChild(tabs);
    const tdiv2=new A();tdiv2.lineStyle(1,0x1e3810,0.4);tdiv2.moveTo(336,88);tdiv2.lineTo(1192,88);this.addChild(tdiv2);

    // Сетка предметов (3×6 = 18 слотов)
    const grid=new e();grid.x=336;grid.y=94;
    for(let i=0;i<18;i++){
      const si=new shmot_elements.lib.Shmot_item();
      si.x=(i%3)*(258+8);si.y=Math.floor(i/3)*(68+6);
      grid['item_'+i]=si;grid.addChild(si);
    }
    this[grid.name='item_grid']=grid;this.addChild(grid);
  }
};

// ── Root MovieClip ─────────────────────────────────────────────────
shmot_elements.lib.shmot_elements=class extends n{
  constructor(){
    super({duration:1,framerate:30});
    const b=new shmot_elements.lib.Shmot_win();
    this[b.name='shmot_win']=b;this.addChild(b);
  }
};
shmot_elements.stage=shmot_elements.lib.shmot_elements}};
